from typing import Sequence

def rank_word(word: Sequence[int], q: int) -> int:
    if q < 1 or any(d < 0 or d >= q for d in word):
        raise ValueError("invalid base-q word")
    rank = 0
    for digit in word:
        rank = q * rank + digit
    return rank

def unrank_word(rank: int, q: int, n: int) -> tuple[int, ...]:
    if q < 1 or n < 0 or not 0 <= rank < q ** n:
        raise ValueError("invalid rank")
    result = [0] * n
    for i in range(n - 1, -1, -1):
        rank, result[i] = divmod(rank, q)
    return tuple(result)

if __name__ == "__main__":
    w = (0, 1, 2, 3) * 4
    r = rank_word(w, 4)
    print(r, unrank_word(r, 4, 16) == w)

from fractions import Fraction
from itertools import product
from typing import Callable

Word = tuple[int, ...]

def exact_probability(q: int, n: int, accepts: Callable[[Word], bool]) -> Fraction:
    if q < 1 or n < 0:
        raise ValueError("invalid dimensions")
    accepted = sum(1 for w in product(range(q), repeat=n) if accepts(w))
    return Fraction(accepted, q ** n)

if __name__ == "__main__":
    print(exact_probability(4, 6, lambda w: sum(w) % 3 == 0))

def de_bruijn(q: int, n: int) -> list[int]:
    if q < 1 or n < 1:
        raise ValueError("positive parameters required")
    a = [0] * (q * n + 1)
    result: list[int] = []
    def visit(t: int, p: int) -> None:
        if t > n:
            if n % p == 0:
                result.extend(a[1:p + 1])
            return
        a[t] = a[t - p]
        visit(t + 1, p)
        for j in range(a[t - p] + 1, q):
            a[t] = j
            visit(t + 1, t)
    visit(1, 1)
    return result

if __name__ == "__main__":
    cycle = de_bruijn(4, 4)
    print(len(cycle), "".join(map(str, cycle[:64])))

